if(!$count)$page='setup';
if(auth()){$uid=(int)$_SESSION['uid'];$s=$db->prepare('SELECT 1 FROM usuarios WHERE id=? AND activo=1');$s->bind_param('i',$uid);$s->execute();if(!$s->get_result()->num_rows){$_SESSION=[];session_regenerate_id(true);flash('error','Tu usuario fue desactivado.');go('index.php');}}

if($_SERVER['REQUEST_METHOD']==='POST'){
