 if($action==='login'){$u=trim((string)$_POST['usuario']);$s=$db->prepare('SELECT id,usuario,nombre,clave,rol FROM usuarios WHERE usuario=? AND activo=1');$s->bind_param('s',$u);$s->execute();$row=$s->get_result()->fetch_assoc();if($row&&password_verify((string)$_POST['clave'],$row['clave'])){session_regenerate_id(true);$_SESSION['uid']=(int)$row['id'];$_SESSION['user']=$row['usuario'];$_SESSION['nombre']=(string)$row['nombre'];$_SESSION['rol']=$row['rol'];$_SESSION['alert_popup']=true;audit($db,'Inicio de sesión');go('index.php');}usleep(300000);flash('error','Datos incorrectos.');go('index.php');}
