 // Nombre, categoría y proveedor se aplican a todas las fechas del mismo producto; cantidad, cambio con proveedor y vencimiento solo a esta fecha
 if($action==='product_update'){$id=(int)($_POST['id']??0);if(!can_edit($db,$id)){flash('error','Solo puedes editar tus productos.');go('index.php?page=productos');}$f=product_fields();if(is_string($f)){flash('error',$f);go('index.php?page=productos');}$s=$db->prepare('SELECT COALESCE(producto_origen_id,id) FROM productos WHERE id=?');$s->bind_param('i',$id);$s->execute();$group=$s->get_result()->fetch_row()[0]??null;if($group===null){flash('error','El producto no existe.');go('index.php?page=productos');}$group=(int)$group;[$name,$cat,$provider,$qty,$exchange,$change,$date]=$f;
  $s=$db->prepare('UPDATE productos SET producto=?,categoria=?,proveedor=? WHERE COALESCE(producto_origen_id,id)=?');$s->bind_param('sssi',$name,$cat,$provider,$group);$s->execute();
  // Si cambia la fecha de aviso o el vencimiento, la alerta de cambio vuelve a quedar pendiente
  $s=$db->prepare('UPDATE productos SET cambio_reportado=IF(fecha_cambio<=>? AND vencimiento=?,cambio_reportado,NULL),cantidad=?,tiene_cambio=?,fecha_cambio=?,vencimiento=? WHERE id=?');$s->bind_param('ssiissi',$change,$date,$qty,$exchange,$change,$date,$id);$s->execute();
  audit($db,'Producto editado: '.$name.' #'.$id);flash('ok','Producto actualizado.');go('index.php?page=productos');}
 if($action==='expiration_add'){$source=(int)($_POST['id']??0);if(!can_edit($db,$source)){flash('error','Solo puedes agregar vencimientos a tus productos.');go('index.php?page=productos');}$qty=max(0,(int)($_POST['cantidad']??0));$date=(string)($_POST['vencimiento']??'');if(!valid_date($date)){flash('error','Selecciona una fecha válida.');go('index.php?page=productos');}$exchange=isset($_POST['tiene_cambio'])?1:0;$change=$exchange?(string)($_POST['fecha_cambio']??''):null;if($exchange&&($error=change_date_error($change,$date))){flash('error',$error);go('index.php?page=productos');}$s=$db->prepare('INSERT INTO productos(codigo,producto,categoria,proveedor,cantidad,tiene_cambio,fecha_cambio,producto_origen_id,vencimiento,usuario_id) SELECT codigo,producto,categoria,proveedor,?,?,?,COALESCE(producto_origen_id,id),?,usuario_id FROM productos WHERE id=?');$s->bind_param('iissi',$qty,$exchange,$change,$date,$source);$s->execute();if(!$s->affected_rows){flash('error','El producto no existe.');go('index.php?page=productos');}audit($db,'Nuevo vencimiento agregado al producto #'.$source);flash('ok','Nueva fecha de vencimiento agregada.');go('index.php?page=productos');}
