 if($action==='profile_save'){$name=mb_substr(trim((string)($_POST['nombre']??'')),0,100)?:null;$uid=(int)$_SESSION['uid'];$s=$db->prepare('UPDATE usuarios SET nombre=? WHERE id=?');$s->bind_param('si',$name,$uid);$s->execute();$_SESSION['nombre']=$name??'';audit($db,'Nombre actualizado: '.($name??'(sin nombre)'));flash('ok','Tu nombre se guardó.');go('index.php?page=perfil');}
 if($action==='product_delete'&&admin()){$id=(int)$_POST['id'];$s=$db->prepare('DELETE FROM productos WHERE id=?');$s->bind_param('i',$id);$s->execute();audit($db,'Producto eliminado #'.$id);flash('ok','Producto eliminado.');go('index.php?page='.(in_array($_POST['volver']??'',['dashboard','alertas'],true)?$_POST['volver']:'productos'));}
 if($action==='user_save'&&admin()){$u=trim((string)$_POST['usuario']);$p=(string)$_POST['clave'];$r=in_array($_POST['rol'],['admin','empleado'],true)?$_POST['rol']:'empleado';$area=trim((string)($_POST['area']??''))?:null;$name=mb_substr(trim((string)($_POST['nombre']??'')),0,100)?:null;if(strlen($u)<3||strlen($p)<10){flash('error','Revisa usuario y contraseña.');go('index.php?page=usuarios');}$h=password_hash($p,PASSWORD_DEFAULT);try{$s=$db->prepare('INSERT INTO usuarios(usuario,nombre,clave,rol,area) VALUES(?,?,?,?,?)');$s->bind_param('sssss',$u,$name,$h,$r,$area);$s->execute();audit($db,'Usuario creado: '.$u.($area!==null?' ('.$area.')':''));flash('ok','Usuario creado.');}catch(Throwable $e){flash('error','El usuario ya existe.');}go('index.php?page=usuarios');}
 if($action==='user_toggle'&&admin()){$id=(int)($_POST['id']??0);if($id===(int)$_SESSION['uid']){flash('error','No puedes desactivar tu propio usuario.');go('index.php?page=usuarios');}$s=$db->prepare('UPDATE usuarios SET activo=1-activo WHERE id=?');$s->bind_param('i',$id);$s->execute();audit($db,'Estado cambiado del usuario #'.$id);flash('ok','Estado del usuario actualizado.');go('index.php?page=usuarios');}
 // Editar usuario (administrador): nombre, usuario de acceso, área y, si se escribe, una contraseña nueva
 if($action==='user_edit'&&admin()){$id=(int)($_POST['id']??0);$login=trim((string)($_POST['usuario']??''));$pass=(string)($_POST['clave']??'');$name=mb_substr(trim((string)($_POST['nombre']??'')),0,100)?:null;$area=trim((string)($_POST['area']??''))?:null;
  if(mb_strlen($login)<3){flash('error','El usuario de acceso debe tener mínimo 3 caracteres.');go('index.php?page=usuarios');}
