  try{$s=$db->prepare('UPDATE usuarios SET usuario=?,nombre=?,area=? WHERE id=?');$s->bind_param('sssi',$login,$name,$area,$id);$s->execute();}catch(Throwable $e){flash('error','Ese usuario de acceso ya lo tiene otra persona.');go('index.php?page=usuarios');}
